#!/usr/bin/env node
/*
 * Builds _api/admin-page-html.js from admin.html.
 *
 * Why: the /admin page is served by the gated /api/admin-page
 * route (gap report A3). Vercel's Node bundler includes files
 * that are literal require()s of a function — a runtime
 * fs.readFileSync of a repo-root static file would NOT be in
 * the bundle. So admin.html is embedded as a generated JS
 * module, exactly like the jobs handler builds its HTML in code.
 *
 * JSON.stringify produces a double-quoted string literal that is
 * a valid JS string literal and is exactly the inverse of JSON
 * parsing — backslashes, backticks, ${...}, newlines and CRLF
 * all round-trip losslessly (hand-rolled template-literal
 * escaping was not).
 *
 * Re-run after EVERY admin.html edit:
 *   node scripts/build-admin-bundle.js
 *
 * tests/phase1-security.test.js fails when the bundle is stale,
 * so a forgotten regeneration is caught by `npm test`.
 */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const src = fs.readFileSync(path.join(root, 'admin.html'), 'utf8').replace(/\r\n?/g, '\n');

const out = `/* Generated by scripts/build-admin-bundle.js — DO NOT EDIT.
   Source of truth: admin.html. Regenerate after every admin.html
   change: node scripts/build-admin-bundle.js */
module.exports = { html: ${JSON.stringify(src)} };
`;

const dest = path.join(root, '_api', 'admin-page-html.js');
fs.writeFileSync(dest, out);
console.log(`wrote ${path.relative(root, dest)} (${src.length} chars from admin.html)`);
